public class Persona {
    String nombre;
    int edad;
    public Persona(String nombre, int edad) {
        this.nombre = nombre;
        this.edad = edad;
    }
    public void presentarse() {
        System.out.println("Soy " + nombre + ", " + edad + " años");
    }
}

public class Estudiante extends Persona {
    public Estudiante(String nombre, int edad) {
        super(nombre, edad);
    }
}
